# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM\'DA İMAN - SALİH AMEL - AHLAK BÜTÜNLÜĞÜ</text>\n  <rect x="25" y="50" width="200" height="185" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">1. SAHİH İMAN (KÖK)</text>\n  <text x="40" y="103" font-size="11" fill="#334155">• Kalp ile tasdik, dil ile ikrar</text>\n  <text x="40" y="125" font-size="11" fill="#334155">• Tevhid bilinci ve samimiyet</text>\n  <text x="40" y="147" font-size="11" fill="#334155">• Ağacın toprağa tutunan</text>\n  <text x="50" y="164" font-size="10.5" fill="#475569">sağlam kökü gibidir; amellere</text>\n  <text x="50" y="181" font-size="10.5" fill="#475569">anlam ve niyet kazandırır.</text>\n  <text x="235" y="140" font-size="20" font-weight="bold" fill="#2563eb">⇄</text>\n  <rect x="250" y="50" width="200" height="185" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">2. SALİH AMEL (GÖVDE)</text>\n  <text x="265" y="103" font-size="11" fill="#334155">• Allah rızasına uygun her</text>\n  <text x="275" y="120" font-size="10.5" fill="#475569">türlü güzel iş ve ibadet</text>\n  <text x="265" y="145" font-size="11" fill="#334155">• İmanı korur, besler ve</text>\n  <text x="275" y="162" font-size="10.5" fill="#475569">hayatta görünür kılar</text>\n  <text x="265" y="187" font-size="10.5" font-weight="bold" fill="#15803d">&quot;İman edip salih amel işleyenler&quot;</text>\n  <text x="265" y="204" font-size="10" fill="#166534">(Asr Suresi, 2-3. ayetler)</text>\n  <text x="460" y="140" font-size="20" font-weight="bold" fill="#16a34a">⇄</text>\n  <rect x="475" y="50" width="200" height="185" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="575" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">3. GÜZEL AHLAK (MEYVE)</text>\n  <text x="490" y="103" font-size="11" fill="#334155">• Doğruluk, emanet, adalet,</text>\n  <text x="500" y="120" font-size="10.5" fill="#475569">merhamet ve sorumluluk</text>\n  <text x="490" y="145" font-size="11" fill="#334155">• İmanın olgunluk ölçüsü:</text>\n  <text x="490" y="165" font-size="10.5" font-weight="bold" fill="#713f12">&quot;Müminlerin imanca en olgunu,</text>\n  <text x="490" y="182" font-size="10.5" font-weight="bold" fill="#713f12">ahlakça en güzel olanıdır.&quot;</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TAKLİDÎ İMAN İLE TAHKİKÎ İMANIN KARŞILAŞTIRILMASI</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">TAKLİDÎ İMAN</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#7c2d12">• Kaynağı: Aile ve sosyal çevreden duyup görme</text>\n  <text x="42" y="122" font-size="11.5" font-weight="bold" fill="#7c2d12">• Yöntemi: Araştırma ve delile dayanmadan kabul</text>\n  <text x="42" y="148" font-size="11.5" font-weight="bold" fill="#7c2d12">• Zayıf Yönü: Şüphe ve itirazlar karşısında</text>\n  <text x="52" y="166" font-size="11" fill="#334155">sarsılma riski taşır, savunması zayıftır</text>\n  <text x="42" y="194" font-size="11.5" font-weight="bold" fill="#7c2d12">• Hükmü: İslam âlimlerinin çoğunluğuna göre</text>\n  <text x="52" y="212" font-size="11" fill="#334155">geçerlidir; ancak delille güçlendirilmelidir</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">TAHKİKÎ İMAN</text>\n  <text x="377" y="96" font-size="11.5" font-weight="bold" fill="#14532d">• Kaynağı: Akıl, vahiy, tefekkür ve sahih bilgi</text>\n  <text x="377" y="122" font-size="11.5" font-weight="bold" fill="#14532d">• Yöntemi: Delillere, araştırmaya ve kavramaya dayalı</text>\n  <text x="377" y="148" font-size="11.5" font-weight="bold" fill="#14532d">• Güçlü Yönü: Şüpheler karşısında sarsılmaz,</text>\n  <text x="387" y="166" font-size="11" fill="#334155">bilinçli kulluk ve iç huzuru (sekînet) sağlar</text>\n  <text x="377" y="194" font-size="11.5" font-weight="bold" fill="#14532d">• Kur\'an\'ın Hedefi: Evreni ve ayetleri düşünerek</text>\n  <text x="387" y="212" font-size="11" fill="#334155">taklidî imandan tahkikî imana yükselmektir</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İMANIN BİREYE VE TOPLUMA KAZANDIRDIKLARI</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">BİREYSEL HAYATA KATKILARI</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#581c87">• Anlam ve Gaye: &quot;Niçin yaratıldım?&quot; sorusuna</text>\n  <text x="52" y="114" font-size="10.5" fill="#334155">cevap vererek varoluşsal boşluğu giderir.</text>\n  <text x="42" y="138" font-size="11.5" font-weight="bold" fill="#581c87">• İç Huzuru ve Güven: Kalplere sekînet verir</text>\n  <text x="52" y="156" font-size="10.5" fill="#334155">(Ra\'d, 28); yalnızlık ve çaresizlik hissini önler.</text>\n  <text x="42" y="180" font-size="11.5" font-weight="bold" fill="#581c87">• Sabır ve Ümit: Musibetlere karşı direnç,</text>\n  <text x="52" y="198" font-size="10.5" fill="#334155">tevekkül ve ahiret bilinciyle sorumluluk kazandırır.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">TOPLUMSAL HAYATA KATKILARI</text>\n  <text x="377" y="96" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Güven Toplumu (el-Mü\'min): Mümin, elinden ve</text>\n  <text x="387" y="114" font-size="10.5" fill="#334155">dilinden herkesin güvende olduğu kimsedir.</text>\n  <text x="377" y="138" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Adalet ve Kul Hakkı Bilinci: İlahi hesap</text>\n  <text x="387" y="156" font-size="10.5" fill="#334155">inancı haksızlığı, hileyi ve zulmü engeller.</text>\n  <text x="377" y="180" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Kardeşlik ve Dayanışma: İnfak, yardımlaşma</text>\n  <text x="387" y="198" font-size="10.5" fill="#334155">ve merhametle toplumsal barışı güçlendirir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
